# -------------------------
# DATA PARSING
# -------------------------

def _clean_csv(text: str) -> str:
    return text.strip().replace("\\", "")


def parse_eskf(text: str):
    reader = csv.DictReader(io.StringIO(_clean_csv(text)))

    t, pos, vel = [], [], []

    for row in reader:
        t.append(float(row["time_s"]))
        pos.append([
            float(row["rov_pos_n"]),
            float(row["rov_pos_e"]),
            float(row["rov_pos_d"]),
        ])
        vel.append([
            float(row["rov_vel_n"]),
            float(row["rov_vel_e"]),
            float(row["rov_vel_d"]),
        ])

    return np.array(t), np.array(pos), np.array(vel)


