# MAIN
# -------------------------

def main():
    print("Parsing arguments...")
    parser = argparse.ArgumentParser(description="Plot RMSE over time.")
    # parser.add_argument("--output-dir", type=Path, default=f"plots_new/{TRAJECTORY_TYPE.value}",)
    parser.add_argument("--no-show", action="store_true")
    args = parser.parse_args()

    pre_fig = "fig8" if TRAJECTORY_TYPE == TrajectoryType.FIGURE_8 else "linear"
    output_dir = Path(f"plots_new/{TRAJECTORY_TYPE.value}")
    # ---- Parse your data strings ----
    eskf_t, eskf_pos, eskf_vel = parse_eskf(eskf_data)
    fgo_t, fgo_pos, fgo_vel = parse_fgo(fgo_data)

    # ---- Generate GT ----
    gt_path = FIG_8_GT_PATH if TRAJECTORY_TYPE == TrajectoryType.FIGURE_8 else LINEAR_TURNS_GT_PATH

    t_gt, rov_gt_pos, rov_gt_vel = load_rov_gt_csv(gt_path)

    # ---- Align GT ----
    eskf_gt_pos = interpolate_gt(t_gt, rov_gt_pos, eskf_t)
    eskf_gt_vel = interpolate_gt(t_gt, rov_gt_vel, eskf_t)

    fgo_gt_pos = interpolate_gt(t_gt, rov_gt_pos, fgo_t)
    fgo_gt_vel = interpolate_gt(t_gt, rov_gt_vel, fgo_t)

    # ---- Compute RMSE ----
    eskf_rmse_pos = compute_rmse(eskf_pos, eskf_gt_pos)
    eskf_rmse_vel = compute_rmse(eskf_vel, eskf_gt_vel)

    fgo_rmse_pos = compute_rmse(fgo_pos, fgo_gt_pos)
    fgo_rmse_vel = compute_rmse(fgo_vel, fgo_gt_vel)

    # ---- Plot ----
    # fig_eskf = plot_rmse(eskf_t, eskf_rmse_pos, eskf_rmse_vel, "ESKF")
    # fig_fgo = plot_rmse(fgo_t, fgo_rmse_pos, fgo_rmse_vel, "FGO")

    overlay_fig = plot_rmse_overlay(
        eskf_t, eskf_rmse_pos, eskf_rmse_vel,
        fgo_t,  fgo_rmse_pos,  fgo_rmse_vel,
    )

    print("GT time range:", t_gt[0], t_gt[-1])
    print("ESKF time range:", eskf_t[0], eskf_t[-1])
    print("FGO time range:", fgo_t[0], fgo_t[-1])

    # ---- Save ----

    output_dir.mkdir(parents=True, exist_ok=True)
    # fig_eskf.savefig(args.output_dir / "eskf_rmse.svg", bbox_inches="tight")
    # fig_fgo.savefig(args.output_dir / "fgo_rmse.svg", bbox_inches="tight")
    overlay_fig.savefig(output_dir / f"{pre_fig}_uuv_error_norm.svg", bbox_inches="tight")

    if not args.no_show:
        plt.show()

